/**
 * Which production path a course is generated by.
 *
 * The panel this feeds used to have exactly one button, and that button assembled
 * from knowledge points. Which route is offered now depends on how far a design
 * has been taken, and the failure mode worth guarding against is the boring one:
 * a design that has properly defined outcomes, evidence and an outline still
 * gets produced the old way, because the panel defaults to what it always did.
 *
 * These tests are about the *decision*, not the rendering. The two arms produce
 * genuinely different courses — different requirement text, different allowed
 * scene types, and one of them gated — so getting the decision wrong is not a
 * cosmetic bug.
 */
import { describe, expect, it } from 'vitest';

import { chooseProductionPath, type ProductionPath } from '@/lib/curriculum/production-path';
import {
  CURRICULUM_DESIGN_PHASES,
  type CurriculumDesignPhase,
  type CurriculumUnitRecord,
} from '@/lib/curriculum/design-types';

function unit(overrides: Partial<CurriculumUnitRecord> = {}): CurriculumUnitRecord {
  return {
    id: 'unit-1',
    taskId: 'task-1',
    parentId: null,
    unitType: 'item',
    title: 'SQL 注入原理',
    code: null,
    unitRole: 'lecture',
    hours: null,
    orderIndex: 0,
    teachingDesign: {},
    deckDesign: {},
    stageId: null,
    createdAt: '2026-01-01T00:00:00.000Z',
    updatedAt: '2026-01-01T00:00:00.000Z',
    ...overrides,
  };
}

function decide(
  phase: CurriculumDesignPhase,
  units: CurriculumUnitRecord[],
  objectiveCount = 2,
): ProductionPath {
  return chooseProductionPath({ phase, units, objectiveCount }).path;
}

describe('choosing a production path', () => {
  it('sends a designed course through the design path from the outline on', () => {
    // The whole point. A task that has settled outcomes, evidence, knowledge,
    // dependencies and an outline must not be produced from knowledge points.
    for (const phase of ['outline', 'teaching', 'assessment', 'review'] as const) {
      expect(decide(phase, [unit()])).toBe('design');
    }
  });

  it('offers the design path with a stated reason when the outline has no item', () => {
    // A disabled button with no reason pushes people to the other button, so
    // the refusal has to carry the fix.
    const chapterOnly = chooseProductionPath({
      phase: 'teaching',
      units: [unit({ unitType: 'chapter', unitRole: null })],
      objectiveCount: 2,
    });
    expect(chapterOnly.path).toBe('design');
    expect(chapterOnly.designAvailable).toBe(false);
    expect(chapterOnly.blockedReason).toContain('条目');
  });

  it('does not treat a chapter as something that can be generated', () => {
    // The chapter is in the units list, so a count-based test would offer it.
    const withChapterAndItem = chooseProductionPath({
      phase: 'outline',
      units: [unit({ unitType: 'chapter', unitRole: null }), unit()],
      objectiveCount: 1,
    });
    expect(withChapterAndItem.designAvailable).toBe(true);
  });

  it('offers the assembler before the outline, and says which work is missing', () => {
    for (const phase of ['task', 'outcomes', 'graph'] as const) {
      expect(decide(phase, [unit()])).toBe('assembly');
    }
    const noOutcomes = chooseProductionPath({
      phase: 'graph',
      units: [],
      objectiveCount: 0,
    });
    expect(noOutcomes.blockedReason).toContain('学习目标');
  });

  it('never offers a path for a phase it does not know', () => {
    // Exhaustive over the declared phases: if a phase is added later, this
    // fails rather than silently falling through to the legacy path.
    for (const phase of CURRICULUM_DESIGN_PHASES) {
      const choice = chooseProductionPath({ phase, units: [unit()], objectiveCount: 2 });
      expect(['design', 'assembly']).toContain(choice.path);
      if (choice.path === 'design' && choice.designAvailable) {
        expect(choice.blockedReason).toBeNull();
      }
    }
  });

  it('always states a reason when the offered path cannot be taken', () => {
    // Either refusal — no items, or not designed yet — must be actionable. A
    // bare `false` is what pushes someone to the other button.
    const noItems = chooseProductionPath({
      phase: 'outline',
      units: [unit({ unitType: 'chapter', unitRole: null })],
      objectiveCount: 2,
    });
    const notDesigned = chooseProductionPath({ phase: 'task', units: [], objectiveCount: 0 });
    for (const choice of [noItems, notDesigned]) {
      expect(choice.designAvailable).toBe(false);
      expect(choice.blockedReason).toBeTruthy();
    }
  });
});
